import type { CreatureDef, MoveDef } from '../creature-types';

/**
 * The Devonian roster: 21 animals across four rungs of a food chain (docs/redesign/08-devonian-
 * domination.md). Lengths are game units chosen so the size-band rule reproduces the chain: same
 * rung reads prey/rival/threat, one rung apart reads threat or giant, two apart always giant. They
 * follow the real animals: adultLength, speed, burst, agility, turnRate and glide are GENERATED by
 * tools/devonian/stats.mjs from docs/research/devonian-swimming.json (representative lengths and
 * swimming performance with sources; docs/research/devonian-swimming.md explains them). Length is
 * 4.6 · metres^0.6, which keeps the real order and near-real proportion inside a playable range;
 * speeds come from body lengths per second with a pace factor and a steering floor. Do not
 * hand-edit those six fields — rerun the script. Rungs follow the sizes that fall out of it
 * (Rhinodipterus, a 0.4 m lungfish, sits in rung II). Localities are labelled because the roster
 * mixes places and times exactly as the Cambrian one does. Every mechanic flag is a game
 * interpretation of anatomy described in docs/redesign/07-devonian-design.md, not a claim of
 * fossil behaviour. Model assets are pending; nothing here depends on them.
 */
const light = (name: string, o: Partial<MoveDef> = {}): MoveDef => ({
  name, windup: 0.14, active: 0.16, recovery: 0.22, damage: 9, poise: 12, knockback: 1.2, stamina: 6, lunge: 0.25, ...o,
});
const heavy = (name: string, o: Partial<MoveDef> = {}): MoveDef => ({
  name, windup: 0.42, active: 0.2, recovery: 0.5, damage: 24, poise: 45, knockback: 3.5, stamina: 18, lunge: 0.9, guardBreak: true, ...o,
});
/** A mouth that cannot bite anything worth biting: filter feeders and the jawless. */
const nibble = (name: string): MoveDef => ({ name, windup: 0.2, active: 0.15, recovery: 0.3, damage: 1, poise: 2, knockback: 0.3, stamina: 4, lunge: 0.1 });

